//! Bundled hook implementations and declarative hook registration.use std::collections::HashMap;use std::net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr};use std::sync::Arc;use std::time::Duration;use async_trait::async_trait;use regex::Regex;use reqwest::header::{HeaderMap, HeaderName, HeaderValue};use serde::{Deserialize, Serialize};use tokio::sync::Semaphore;use crate::hooks::{    Hook, HookContext, HookError, HookEvent, HookFailureMode, HookOutcome, HookPoint, HookRegistry,};const DEFAULT_RULE_PRIORITY: u32 = 100;const DEFAULT_WEBHOOK_PRIORITY: u32 = 300;const DEFAULT_WEBHOOK_TIMEOUT_MS: u64 = 2000;const DEFAULT_WEBHOOK_MAX_IN_FLIGHT: usize = 32;const MAX_HOOK_TIMEOUT_MS: u64 = 30_000;const ALL_HOOK_POINTS: [HookPoint; 6] = [    HookPoint::BeforeInbound,    HookPoint::BeforeToolCall,    HookPoint::BeforeOutbound,    HookPoint::OnSessionStart,    HookPoint::OnSessionEnd,    HookPoint::TransformResponse,];/// Errors while parsing or compiling declarative hook bundles.#[derive(Debug, thiserror::Error)]pub enum HookBundleError {    #[error("Invalid hook bundle format: {0}")]    InvalidFormat(String),    #[error("Hook '{hook}' must declare at least one hook point")]    MissingHookPoints { hook: String },    #[error("Hook '{hook}' has invalid regex '{pattern}': {reason}")]    InvalidRegex {        hook: String,        pattern: String,        reason: String,    },    #[error("Hook '{hook}' timeout must be between 1 and {max_ms} ms")]    InvalidTimeout { hook: String, max_ms: u64 },    #[error("Outbound webhook hook '{hook}' has invalid url: {url}")]    InvalidWebhookUrl { hook: String, url: String },    #[error("Outbound webhook hook '{hook}' must use https, got '{scheme}'")]    InvalidWebhookScheme { hook: String, scheme: String },    #[error("Outbound webhook hook '{hook}' cannot target host '{host}'")]    ForbiddenWebhookHost { hook: String, host: String },    #[error("Outbound webhook hook '{hook}' has invalid header '{header}': {reason}")]    InvalidWebhookHeader {        hook: String,        header: String,        reason: String,    },    #[error("Outbound webhook hook '{hook}' cannot set restricted header '{header}'")]    ForbiddenWebhookHeader { hook: String, header: String },    #[error("Outbound webhook hook '{hook}' max_in_flight must be at least 1")]    InvalidWebhookMaxInFlight { hook: String },}/// A declarative hook bundle loaded from workspace files or extension capabilities.////// Supports two bundled hook types:/// - Rule hooks (`rules`) for reject/regex transform/prepend/append logic/// - Outbound webhook hooks (`outbound_webhooks`) for fire-and-forget event delivery#[derive(Debug, Clone, Default, Serialize, Deserialize)]pub struct HookBundleConfig {    /// Declarative content/tool/session rules.    #[serde(default)]    pub rules: Vec<HookRuleConfig>,    /// Fire-and-forget webhook notifications on selected hook points.    #[serde(default)]    pub outbound_webhooks: Vec<OutboundWebhookConfig>,}impl HookBundleConfig {    /// Parse a hook bundle from JSON value.    ///    /// Accepts either:    /// - object form: `{ "rules": [...], "outbound_webhooks": [...] }`    /// - array form:  `[ {rule}, {rule} ]` (shorthand for rules only)    pub fn from_value(value: &serde_json::Value) -> Result<Self, HookBundleError> {        if value.is_array() {            let rules: Vec<HookRuleConfig> = serde_json::from_value(value.clone())                .map_err(|e| HookBundleError::InvalidFormat(e.to_string()))?;            return Ok(Self {                rules,                outbound_webhooks: Vec::new(),            });        }        serde_json::from_value(value.clone())            .map_err(|e| HookBundleError::InvalidFormat(e.to_string()))    }}/// Summary of hook registrations performed from a bundle.#[derive(Debug, Default, Clone, Copy)]pub struct HookRegistrationSummary {    /// Number of non-webhook hook registrations (audit/rule hooks).    pub hooks: usize,    /// Number of outbound webhook hook registrations.    pub outbound_webhooks: usize,    /// Number of invalid/failed registrations skipped.    pub errors: usize,}impl HookRegistrationSummary {    /// Total number of hooks successfully registered.    pub fn total_registered(&self) -> usize {        self.hooks + self.outbound_webhooks    }    pub fn merge(&mut self, other: HookRegistrationSummary) {        self.hooks += other.hooks;        self.outbound_webhooks += other.outbound_webhooks;        self.errors += other.errors;    }}/// Register bundled built-in hooks that ship with IronClaw.pub async fn register_bundled_hooks(registry: &Arc<HookRegistry>) -> HookRegistrationSummary {    registry        .register_with_priority(Arc::new(AuditLogHook), 25)        .await;    HookRegistrationSummary {        hooks: 1,        outbound_webhooks: 0,        errors: 0,    }}/// Register all hooks from a declarative bundle.